<?php
// Start of password v.
/**
 * <p>
 * <b>PASSWORD_BCRYPT</b> is used to create new password
 * hashes using the <b>CRYPT_BLOWFISH</b> algorithm.
 * </p>
 * <p>
 * This will always result in a hash using the "$2y$" crypt format,
 * which is always 60 characters wide.
 * </p>
 * <p>
 * Supported Options:
 * </p>
 * <ul>
 * <li>
 * <p>
 * <em>salt (string)</em> - to manually provide a salt to use when hashing the password.
 * Note that this will override and prevent a salt from being automatically generated.
 * </p>
 * <p>
 * If omitted, a random salt will be generated by {@link "https://php.net/manual/en/function.password-hash.php" password_hash()} for
 * each password hashed. This is the intended mode of operation.
 * </p>
 * <b>Warning</b>
 * <p>
 * The salt option is deprecated. It is now preferred to simply use the salt
 * that is generated by default. As of PHP 8.0.0, an explicitly given salt is
 * ignored.
 * </p>
 * </li>
 * <li>
 * <p>
 * <em>cost (int)</em> - which denotes the algorithmic cost that should be used.
 * Examples of these values can be found on the {@link "https://php.net/manual/en/function.crypt.php crypt()"} page.
 * </p>
 * <p>
 * If omitted, a default value of <em>12</em> will be used. This is a good
 * baseline cost, but you may want to consider increasing it depending on your hardware.
 * </p>
 * </li>
 * </ul>
 * @link https://php.net/manual/en/password.constants.php
 */

use JetBrains\PhpStorm\ArrayShape;
use JetBrains\PhpStorm\Internal\LanguageLevelTypeAware;

/**
 * <p>
 * The default algorithm to use for hashing if no algorithm is provided. This
 * may change in newer PHP releases when newer, stronger hashing algorithms are
 * supported.
 * </p>
 * <p>
 * It is worth noting that over time this constant can change. It is thus
 * important to be aware that the length of the resulting hash can change.
 * Therefore, when using PASSWORD_DEFAULT the resulting hash must be stored in a
 * way that can store arbitrary hashes, the recommended width is 255 bytes.
 * </p>
 * <p>
 * Currently is an alias for PASSWORD_BCRYPT.
 * </p>
 */
define("PASSWORD_DEFAULT", "2y");

/**
 * <p>
 * Default algorithmic cost used by password_hash() when hashing passwords with
 * PASSWORD_BCRYPT.
 * </p>
 * <p>
 * Available as of PHP 7.0.0.
 * </p>
 */
define("PASSWORD_BCRYPT_DEFAULT_COST", 12);

/**
 * <p>
 * PASSWORD_BCRYPT is used to create new password hashes using the
 * CRYPT_BLOWFISH algorithm.
 * </p>
 * <p>
 * This will always result in a hash using the "$2y$" crypt format, which is
 * always 60 characters wide.
 * </p>
 * <p>
 * Supported Options:
 * </p>
 * <ul>
 * <li>
 * <p>
 * salt (string) - to manually provide a salt to use when hashing the password.
 * Note that this will override and prevent a salt from being automatically
 * generated.
 * </p>
 * <p>
 * If omitted, a random salt will be generated by password_hash() for each
 * password hashed. This is the intended mode of operation and as of PHP 7.0.0
 * the salt option has been deprecated.
 * </p>
 * </li>
 *
 * <li>
 * <p>
 * cost (int) - which denotes the algorithmic cost that should be used. Examples
 * of these values can be found on the crypt() page.
 * </p>
 * <p>
 * If omitted, a default value of <em>12</em> will be used. This is a good
 * baseline cost, but you may want to consider increasing it depending on your
 * hardware.
 * </p>
 * </li>
 * </ul>
 */
define("PASSWORD_BCRYPT", '2y');

/**
 * PASSWORD_ARGON2I is used to create new password hashes using the Argon2i algorithm.
 *
 * Supported Options:
 * <ul>
 * <li>memory_cost (int) - Maximum memory (in kibibytes) that may be used to compute the Argon2 hash. Defaults to PASSWORD_ARGON2_DEFAULT_MEMORY_COST.</li>
 *
 * <li>time_cost (int) - Number of iterations (passes) used to compute the Argon2 hash. Defaults to PASSWORD_ARGON2_DEFAULT_TIME_COST.</li>
 *
 * <li>threads (int) - Number of threads to use for computing the Argon2 hash. Defaults to PASSWORD_ARGON2_DEFAULT_THREADS. Only available with libargon2, not with libsodium implementation.</li>
 * </ul>
 * Available as of PHP 7.2.0.
 * @since 7.2
 */
define('PASSWORD_ARGON2I', 'argon2i');

/**
 * PASSWORD_ARGON2ID is used to create new password hashes using the Argon2id algorithm.
 *
 * Supported Options:
 * <ul>
 * <li>memory_cost (int) - Maximum memory (in kibibytes) that may be used to compute the Argon2 hash. Defaults to PASSWORD_ARGON2_DEFAULT_MEMORY_COST.</li>
 *
 * <li>time_cost (int) - Number of iterations (passes) used to compute the Argon2 hash. Defaults to PASSWORD_ARGON2_DEFAULT_TIME_COST.</li>
 *
 * <li>threads (int) - Number of threads to use for computing the Argon2 hash. Defaults to PASSWORD_ARGON2_DEFAULT_THREADS. Only available with libargon2, not with libsodium implementation.</li>
 * </ul>
 * Available as of PHP 7.3.0.
 * @since 7.3
 */
define('PASSWORD_ARGON2ID', 'argon2id');

/**
 * Default amount of memory in kibibytes (KiB) that will be used to compute a hash.
 * Available as of PHP 7.2.0.
 * @since 7.2
 */
define('PASSWORD_ARGON2_DEFAULT_MEMORY_COST', 65536);

/**
 * Default number of iterations (passes) used to compute a hash.
 * Available as of PHP 7.2.0.
 * @since 7.2
 */
define('PASSWORD_ARGON2_DEFAULT_TIME_COST', 4);

/**
 * Default number of threads that Argon2lib will use. Not available with libsodium implementation.
 * Available as of PHP 7.2.0.
 * @since 7.2
 */
define('PASSWORD_ARGON2_DEFAULT_THREADS', 1);

/**
 * Available as of PHP 7.4.0.
 * @since 7.4
 */
define('PASSWORD_ARGON2_PROVIDER', 'standard');

/**
 * Returns information about the given hash
 * @link https://php.net/manual/en/function.password-get-info.php
 * @param string $hash A hash created by <a href="https://php.net/manual/en/function.password-hash.php" class="link">password_hash()</a>.
 * @return array|null Returns an associative array with three elements:
 * <ul>
 * <li>
 * <em>algo</em>, which will match a
 * {@link https://php.net/manual/en/password.constants.php password algorithm constant}
 * </li>
 * <li>
 * <em>algoName</em>, which has the human readable name of the algorithm
 * </li>
 * <li>
 * <em>options</em>, which includes the options
 * provided when calling  @link https://php.net/manual/en/function.password-hash.php" password_hash()
 * </li>
 * </ul>
 * @since 5.5
 */
#[ArrayShape(["algo" => "int", "algoName" => "string", "options" => "array"])]
#[LanguageLevelTypeAware(['8.0' => 'array'], default: 'array|null')]
#[Pure]
function password_get_info(string $hash) {}

/**
 * (PHP 5 &gt;= 5.5.0, PHP 5)<br/>
 *
 * Creates a password hash
 * @link https://php.net/manual/en/function.password-hash.php
 * @param string $password <p> The user's password.</p>
 * <b>Caution</b>
 * <p>
 * Using the <a href="https://php.net/manual/en/password.constants.php" class="link">PASSWORD_BCRYPT</a>
 * as the algorithm, will result in the password parameter being truncated to a
 * maximum length of 72 bytes.
 * </p>
 * @param string|int|null $algo A <a href="https://php.net/manual/en/password.constants.php" class="link">password algorithm constant</a>  denoting the algorithm to use when hashing the password.
 * @param array $options [optional] <p> An associative array containing options. See the <a href="https://php.net/manual/en/password.constants.php" class="link">password algorithm constants</a> for documentation on the supported options for each algorithm.</p>
 * If omitted, a random salt will be created and the default cost will be used.
 * @return string <p>Returns the hashed password.</p>
 * <p>
 * The used algorithm, cost and salt are returned as part of the hash.
 * Therefore, all information that's needed to verify the hash is included in
 * it. This allows the <a href="https://www.php.net/manual/en/function.password-verify.php" class="link">password_verify()</a>
 * function to verify the hash without needing separate storage for the salt or
 * algorithm information.
 * </p>
 * @since 5.5
 */
#[LanguageLevelTypeAware(["8.0" => "string"], default: "string|false|null")]
#[Pure(true)]
function password_hash(string $password, string|int|null $algo, array $options = []) {}

/**
 * Checks if the given hash matches the given options
 * @link https://php.net/manual/en/function.password-needs-rehash.php
 * @param string $hash A hash created by <a href="https://php.net/manual/en/function.password-hash.php" class="link">password_hash()</a>.
 * @param string|int|null $algo A <a href="https://php.net/manual/en/password.constants.php" class="link">password algorithm constant</a> denoting the algorithm to use when hashing the password.
 * @param array $options [optional] <p> An associative array containing options. See the password algorithm constants for documentation on the supported options for each algorithm.</p>
 * @return bool Returns TRUE if the hash should be rehashed to match the given algo and options, or FALSE otherwise.
 * @since 5.5
 */
#[Pure]
function password_needs_rehash(string $hash, string|int|null $algo, array $options = []): bool {}

/**
 * Verifies that a password matches a hash
 * @link https://php.net/manual/en/function.password-verify.php
 * @param string $password The user's password.
 * @param string $hash A hash created by <a href="https://php.net/manual/en/function.password-hash.php" class="link">password_hash()</a>.
 * @return bool Returns TRUE if the password and hash match, or FALSE otherwise.
 * @since 5.5
 */
#[Pure]
function password_verify(string $password, string $hash): bool {}

/**
 * Get available password hashing algorithm IDs
 * @link https://php.net/manual/en/function.password-algos.php
 * @return string[] Returns the available password hashing algorithm IDs.
 * @since 7.4
 */
#[Pure]
function password_algos(): array {}
// End of password v.
